"""Meeting room: peripheral offices around a locked central conference chamber."""
from pathlib import Path
import json,random
D=Path(__file__).resolve().parents[1]/'game/data';g=[[0]*35 for _ in range(35)];rng=random.Random(150904)
for x0,x1,y0,y1 in [(1,9,1,33),(25,33,1,33),(13,21,1,9),(13,21,25,33)]:
 stack=[(x0,y0)];g[y0][x0]=1
 while stack:
  x,y=stack[-1];ns=[(x+dx,y+dy) for dx,dy in [(2,0),(-2,0),(0,2),(0,-2)] if x0<=x+dx<=x1 and y0<=y+dy<=y1 and not g[y+dy][x+dx]]
  if not ns:stack.pop();continue
  a,b=rng.choice(ns);g[(y+b)//2][(x+a)//2]=g[b][a]=1;stack.append((a,b))
for x in range(11,24):g[11][x]=g[23][x]=1
for y in range(11,24):g[y][11]=g[y][23]=1
for y in range(13,22):
 for x in range(13,22):g[y][x]=1
