for x in range(23,26):g[17][x]=1
for y in range(9,14):g[y][17]=1
for y in range(21,26):g[y][17]=1
E=[];en=json.loads((D/'en.json').read_text())
def tr(fr,eng):en[fr]=eng;return fr
def ev(id,kind,cell,ref,title,text,**kw):
 e=dict(id=id,kind=kind,cell=cell,ref=str(ref),title=tr(*title),text=tr(*text),**kw);E.append(e);return e
def result(e,fr,eng):e['success']=tr(fr,eng)
ev('r_welcome','clue',[13,23],100,('Préparer le comité','Prepare the committee'),('La salle centrale est condamnée depuis l’incident. Le placement 203 ouvre les bureaux de planification à l’est. Le planning 303 ouvre les trois accès à la salle. Préparez ensuite la conférence en 403.','The central room has been sealed since the incident. Seating station 203 opens the eastern scheduling offices. Planner 303 opens the three room entrances. Then prepare the conference at 403.'))
ev('r_east','door',[24,17],101,('Bureaux de planification','Scheduling offices'),('Les invitations doivent être placées en 203 avant l’ouverture.','Invitations must be seated at 203 before access opens.'),axis='x',controlled_by='r_seating')
for id,cell,ref,axis in [('r_westdoor',[12,17],102,'x'),('r_northdoor',[17,12],103,'y'),('r_southdoor',[17,22],104,'y')]:ev(id,'door',cell,ref,('Accès à la salle '+str(ref),'Meeting room entrance '+str(ref)),('Le planning 303 doit être validé. Cet accès restera ouvert dans les deux sens.','Planner 303 must be approved. This entrance will remain open in both directions.'),axis=axis,controlled_by='r_schedule')
ev('r_final','exit',[21,21],105,('Présidence du comité','Committee chair'),('La conférence est prête lorsque le placement, le planning et les branchements sont validés. Lancez alors la réunion.','The conference is ready once seating, scheduling and connections are approved. Then start the meeting.'),prerequisites=['r_seating','r_schedule','r_conference'],action=tr('Ouvrir la réunion','Open the meeting'))
ev('r_badges','pickup',[1,1],201,('Invitations du comité','Committee invitations'),('Six invités : Aster, Boréal, Cobalt, Delta, Écho et Fermi. Aucun n’a indiqué de préférence alimentaire. Les six signatures sont étrangement identiques. Pour le pupitre 203.','Six guests: Aster, Boréal, Cobalt, Delta, Echo and Fermi. None listed dietary preferences. All six signatures look strangely identical. For lectern 203.'),resource='guest_badges',amount=1,appearance='card')
ev('r_seat_note','clue',[9,1],202,('Demandes des invités','Guest requests'),('Places numérotées dans le sens horaire : 1 en haut, puis 2 et 3 à droite, 4 en bas, 5 et 6 à gauche. La porte est en bas. Aster veut lui faire face : place 1. Delta exige la place suivante dans le sens horaire après Aster. Écho veut être en face de Delta. Fermi doit être voisin du président, mais pas d’Écho. Cobalt refuse d’être voisin de Delta.','Seats are numbered clockwise: 1 at the top, then 2 and 3 on the right, 4 at the bottom, 5 and 6 on the left. The door is below. Aster wants to face it: seat 1. Delta demands the next clockwise seat after Aster. Echo wants to sit opposite Delta. Fermi must sit next to the chair, but not Echo. Cobalt refuses to sit next to Delta.'))
e=ev('r_seating','mechanism',[5,17],203,('Plan de table','Seating plan'),('Installez les invitations. Attribuez une place de 1 à 6 à chaque invité selon les demandes 202 et la décision officielle 204. Un seul invité par place. Le tableau montre les places occupées.','Install the invitations. Assign each guest a seat from 1 to 6 using requests 202 and official decision 204. One guest per seat. The board shows occupied seats.'),requires=['guest_badges'],puzzle_type='seating',model='seating',opens=['r_east'])
result(e,'Placement accepté. Les bureaux de planification sont ouverts. « Ils se détestent déjà. Excellent signe d’indépendance intellectuelle. » — Folamour','Seating approved. The scheduling offices are open. “They already hate each other. An excellent sign of intellectual independence.” — Folamour')
ev('r_president','clue',[1,33],204,('Décision officielle du secrétariat','Official secretariat decision'),('Boréal préside la réunion et occupe la place 4. Cobalt revendique le titre, mais sa demande a été rejetée. La place du président tourne le dos à la porte, comme il l’exige.','Boreal chairs the meeting and occupies seat 4. Cobalt claims the title, but his request was rejected. The chair’s seat has its back to the door, as he demands.'))
ev('r_agenda','pickup',[25,1],301,('Dossier de séance','Meeting agenda file'),('Quatre interventions à programmer entre 09 h 00 et 10 h 00. Un créneau dure dix minutes. Installez le dossier au planning 303.','Four items to schedule between 09:00 and 10:00. Each slot lasts ten minutes. Install the file at planner 303.'),resource='agenda_file',amount=1,appearance='card')
ev('r_schedule_note','clue',[33,1],302,('Contraintes horaires','Scheduling constraints'),('Ouverture : 10 min, commence à 09 h 00. Rapport : 20 min. Démonstration : 20 min. Vote : 10 min, termine à 10 h 00. Le rapport doit être terminé avant la démonstration. Aucune pause et aucun chevauchement.','Opening: 10 min, begins at 09:00. Report: 20 min. Demonstration: 20 min. Vote: 10 min, ends at 10:00. The report must finish before the demonstration. No breaks and no overlaps.'))
e=ev('r_schedule','mechanism',[29,17],303,('Planning du comité','Committee planner'),('Installez le dossier. Choisissez l’heure de début de chaque intervention. Le tableau des six créneaux montre les occupations ; deux interventions dans la même case signalent un chevauchement. Les durées sont fixes.','Install the file. Choose each item’s start time. The six-slot board shows occupancy; two items in a slot indicate an overlap. Durations are fixed.'),requires=['agenda_file'],puzzle_type='schedule',model='schedule',durations=[1,2,2,1],opens=['r_westdoor','r_northdoor','r_southdoor'])
result(e,'Planning validé. Les trois accès à la salle centrale s’ouvrent. « Soixante minutes de réunion. Je prévois quatre-vingts minutes de conclusions. » — Folamour','Schedule approved. The three central room entrances open. “Sixty minutes of meeting. I foresee eighty minutes of conclusions.” — Folamour')
ev('r_schedule_tip','clue',[33,33],304,('Note de séance','Session note'),('Les quatre durées remplissent exactement l’heure disponible. Le vote occupe le dernier créneau. Le rapport et la démonstration doivent chacun occuper deux cases consécutives.','The four durations fill the available hour exactly. The vote occupies the final slot. Report and demonstration must each occupy two consecutive slots.'))
ev('r_cables','pickup',[13,33],401,('Valise de câbles','Cable case'),('Quatre liaisons pour la conférence 403. Elles restent installées pendant les essais. Les branchements sont simulés sans endommager le matériel.','Four connections for conference station 403. They remain installed during trials. Connections are simulated without damaging the equipment.'),resource='conference_cables',amount=1,appearance='key')
ev('r_wiring_note','clue',[13,1],402,('Schéma de conférence','Conference wiring plan'),('L’image doit suivre CAMÉRA → ARCHIVES → PROJECTEUR → ÉCRANS, pour conserver une copie avant diffusion. Le MICRO doit rejoindre directement l’AMPLIFICATEUR. Entrées : A = projecteur ; B = archives ; C = écrans ; D = amplificateur. Une seule liaison par entrée.','The image must follow CAMERA → ARCHIVE → PROJECTOR → SCREENS, saving a copy before broadcast. The MICROPHONE must connect directly to the AMPLIFIER. Inputs: A = projector; B = archive; C = screens; D = amplifier. One connection per input.'))
e=ev('r_conference','mechanism',[17,17],403,('Système de conférence','Conference system'),('Installez la valise. Branchez chaque sortie sur une entrée A à D selon le schéma 402, puis testez. Le trajet de l’image et celui du son sont affichés. Validez lorsque les deux trajets sont conformes.','Install the case. Connect each output to input A to D using plan 402, then test. Image and sound routes are displayed. Validate when both routes are correct.'),requires=['conference_cables'],prerequisites=['r_seating','r_schedule'],puzzle_type='conference',model='conference')
result(e,'Image archivée, écrans prêts, son opérationnel. Ouvrez la réunion en 105. « Vous entendrez bientôt plusieurs opinions. N’en tirez pas de conclusions sur le nombre de personnes. » — Folamour','Image archived, screens ready, sound operational. Open the meeting at 105. “You will soon hear several opinions. Do not infer the number of people from that.” — Folamour')
for id,cell,ref,fr,eng in [('r_secret1',[9,33],205,'Registre des congés : aucun membre du comité n’a pris de vacances. Motif commun : « Pas de corps à reposer. »','Leave register: no committee member has taken a holiday. Shared reason: “No body to rest.”'),('r_secret2',[25,33],305,'Commande du traiteur : six fois « rien ». Le secrétariat demande tout de même six serviettes.','Catering order: six portions of “nothing”. The secretariat still requests six napkins.'),('r_secret3',[21,9],404,'Projet MIROIR : les instances débattent entre elles. La procédure d’unification reste verrouillée. Autorisation requise après la réunion du comité.','MIRROR project: instances debate each other. The unification procedure remains locked. Authorisation required after the committee meeting.')]:ev(id,'clue',cell,ref,('Archive du comité '+str(ref),'Committee archive '+str(ref)),(fr,eng),secret=True)
